import math


def expand(axiom, rules, depth):
    if depth < 0:
        raise ValueError("depth must not be negative")
    for predecessor in rules:
        if len(predecessor) != 1:
            raise ValueError(f"predecessor {predecessor!r} must be a single symbol")
    current = axiom
    for _ in range(depth):
        current = "".join(rules.get(symbol, symbol) for symbol in current)
    return current


def turtle(commands, angle_deg, step=1.0, start=(0.0, 0.0), heading_deg=0.0):
    if commands.count("[") != commands.count("]"):
        raise ValueError("unbalanced brackets")
    x, y = start
    heading = heading_deg
    stack = []
    segments = []
    for symbol in commands:
        if symbol in ("F", "f"):
            radians = math.radians(heading)
            nx = x + step * math.cos(radians)
            ny = y + step * math.sin(radians)
            if symbol == "F":
                segments.append(((x, y), (nx, ny)))
            x, y = nx, ny
        elif symbol == "+":
            heading -= angle_deg
        elif symbol == "-":
            heading += angle_deg
        elif symbol == "[":
            stack.append((x, y, heading))
        elif symbol == "]":
            if not stack:
                raise ValueError("']' with nothing pushed")
            x, y, heading = stack.pop()
    return segments
